import {mainCategories} from './categories.js';
export const menuButton=()=>'<button type="button" class="icon-btn menu-toggle" aria-label="Открыть меню" aria-haspopup="dialog" aria-expanded="false"><svg viewBox="0 0 28 28" aria-hidden="true"><path d="M3 6h22M3 14h16M3 22h22"/></svg></button>';
export function bindSiteMenu({brand,brands,escape:esc,onCatalog,onSearch}){
 let drawer,trigger;
 function close(){drawer?.close();}
 document.addEventListener('click',event=>{
  const button=event.target.closest('.menu-toggle');if(!button)return;
  trigger=button;drawer=document.createElement('dialog');drawer.className='site-menu';drawer.setAttribute('aria-label','Меню магазина');
  drawer.innerHTML=`<div class="site-menu-top">${brand()}<button type="button" class="icon-btn" data-menu-close aria-label="Закрыть меню">×</button></div><form class="site-menu-search"><label class="sr-only" for="menu-search">Поиск</label><input id="menu-search" name="q" type="search" placeholder="Найти бренд или вещь"><button type="submit">Найти</button></form><nav aria-label="Разделы магазина"><a href="#/catalog" data-menu-catalog>Весь каталог</a>${[['men','Мужское'],['women','Женское'],['kids','Детское']].map(([id,label])=>`<details class="menu-audience" name="menu-audience"><summary>${label}</summary><div class="site-menu-categories"><a href="#/catalog" data-menu-audience="${id}">Все товары · ${label.toLowerCase()}</a>${mainCategories.map(category=>`<a href="#/catalog/${encodeURIComponent(category)}" data-menu-audience="${id}" data-menu-category="${esc(category)}">${esc(category)}</a>`).join('')}</div></details>`).join('')}<details><summary>Бренды</summary><div class="site-menu-brands"><input type="search" class="brand-search" data-brand-search placeholder="Найти бренд" aria-label="Поиск бренда">${brands().map(b=>`<a href="#/catalog" data-menu-brand="${esc(b.id)}">${esc(b.name)}</a>`).join('')||'<p>Бренды пока не добавлены</p>'}</div></details><a href="#/catalog" data-menu-sale>Скидки</a><a href="#/about">О магазине</a><a href="#/contact">Контакты</a></nav>`;
  document.body.append(drawer);trigger.setAttribute('aria-expanded','true');document.documentElement.classList.add('menu-open');
  drawer.addEventListener('close',()=>{document.documentElement.classList.remove('menu-open');trigger?.setAttribute('aria-expanded','false');drawer.remove();trigger?.focus();});
  drawer.addEventListener('click',e=>{if(e.target.closest('[data-menu-close]'))return close();if(e.target===drawer){const box=drawer.getBoundingClientRect();if(e.clientX>box.right||e.clientY>box.bottom||e.clientX<box.left||e.clientY<box.top)close();return;}const link=e.target.closest('a');if(!link)return;if(link.matches('[data-menu-catalog],[data-menu-audience],[data-menu-brand],[data-menu-sale]')){e.preventDefault();close();onCatalog({audience:link.dataset.menuAudience||'',category:link.dataset.menuCategory||'',brands:link.dataset.menuBrand?[link.dataset.menuBrand]:[],sale:link.hasAttribute('data-menu-sale')});}else close();});
  drawer.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const query=new FormData(e.target).get('q').trim();close();onSearch(query);});drawer.showModal();
 });
}
